import { resetError, updateLoader, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Row } from '../../../../../../commonStyle/index.style'
import { Container, CustomText } from '../../../../../../components'
import BottomBtn from '../../../../../../components/BottomBtn'
import InfoHeader from '../../../../../../components/InfoHeader'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import StepsHeader from '../../../../../../components/StepsHeader'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { OFFLINE_FORM_DATA } from '../../../../../../constants/cookies'
import { ADDITIONAL_INFORMATION_REQUIRED, DOCUMENT_INCOMPLETE, FLEET_POLICY, MANUAL_ORDER, SUBMITTED } from '../../../../../../constants/pkgCode'
import { getCreateOfflineQuoteBody } from '../../../../../../helpers/getPackageBody'
import { getFromLocalStorageData } from '../../../../../../helpers/localstorage'
import { SEND_GOLD_ICON } from '../../../../../../images'
import { LANG_STRINGS } from '../../../../../../lang'
import OfflinePolicyContainer from '../../../../../CommonContainer/OfflinePolicyContainer'
import { useCreateOfflineQuote, useGetOfflineQuoteDetail } from '../../../state/hooks/usePolicyState'
import { OfflinePolicyReviewStyle } from './index.style'

function OfflinePolicyReviewContainer ({ match, history }) {
  const urlParams = useMemo(() => match?.params || {}, [match])
  const [{ offlineQuoteDetailData = {} }, offlineQuoteDetailReq] = useGetOfflineQuoteDetail()
  const [pageConfig, setPageConfig] = useState((() => {
    // if order id exist then it means to show the detail page
    let config = {
      isOfflineOrderDetail: false
    }
    if (urlParams.policyId) {
      config = {
        ...config,
        title: LANG_STRINGS.orderDetails,
        quoteId: urlParams.policyId,
        isOfflineOrderDetail: true
      }
    } else if (urlParams.purchaseType) {
      const isManualOrder = urlParams.purchaseType === MANUAL_ORDER
      const title = isManualOrder ? LANG_STRINGS.mobilManualOrder : `Mobil: ${LANG_STRINGS.fleet}`
      config.title = title
      config = {
        ...config,
        title,
        isManualOrder,
        showEditQuoteData: true
      }
    }
    return config
  })())

  const disabledBtn = useMemo(() => {
    return [SUBMITTED, DOCUMENT_INCOMPLETE, ADDITIONAL_INFORMATION_REQUIRED].includes(offlineQuoteDetailData?.status)
  }, [offlineQuoteDetailData?.status])

  const [offlineLocalData, setOfflineLocalData] = useState(
    getCreateOfflineQuoteBody({
      ...getFromLocalStorageData(OFFLINE_FORM_DATA),
      protection_case: pageConfig.isManualOrder ? MANUAL_ORDER : FLEET_POLICY
    })
  )

  const [{ CREATE_OFFLINE_QUOTE_LOADER, OFFLINE_QUOTE_DETAIL_LOADER }, dispatchLoader] = useLoaderContextValue()
  const [{ createOfflineQuoteStatus, offlineQuoteDetailStatus }, dispatchError] = useErrorContextValue() // createOfflineQuoteErrorData
  const [{ createOfflineQuoteData }, createOfflineQuoteRequest] = useCreateOfflineQuote()
  const that = useRef({})

  useEffect(() => {
    if (urlParams.policyId && OFFLINE_QUOTE_DETAIL_LOADER === undefined) {
      offlineQuoteDetailReq({
        quoteId: urlParams.policyId
      })
    }
  }, [urlParams.policyId, OFFLINE_QUOTE_DETAIL_LOADER, offlineQuoteDetailReq])

  useEffect(() => {
    if (createOfflineQuoteStatus === 'success') {
      history.push(`/offline/success/${createOfflineQuoteData.id}`)
      dispatchError(resetError({
        createOfflineQuoteStatus: undefined
      }))
    } else if (createOfflineQuoteStatus) {
      ShowSnackbar.error({
        visible: true,
        text: createOfflineQuoteStatus
      })
      dispatchError(resetError({
        createOfflineQuoteStatus: undefined
      }))
    }

    if (offlineQuoteDetailStatus === 'success') {
      setOfflineLocalData(offlineQuoteDetailData.policy_details)
      setPageConfig(pageConfig => ({
        ...pageConfig,
        showEditQuoteData: [DOCUMENT_INCOMPLETE].includes(offlineQuoteDetailData.status),
        isManualOrder: offlineQuoteDetailData?.policy_details?.protection_case === MANUAL_ORDER
      }))
      dispatchError(resetError({
        offlineQuoteDetailStatus: undefined
      }))
    }
  }, [
    createOfflineQuoteStatus, offlineQuoteDetailStatus, dispatchError,
    history, offlineQuoteDetailData, createOfflineQuoteData
  ])

  useEffect(() => {
    return () => {
      // reset the loader once the page state update
      // or redirect to new page
      dispatchLoader(updateLoader({
        OFFLINE_QUOTE_DETAIL_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  const handleSubmit = useCallback(() => {
    const body = {
      ...offlineLocalData,
      instant_approve: that.current.instantChecked,
      vehicle_sum_insured: Number(offlineLocalData.vehicle_sum_insured)
    }
    body.additional_sum_insured = 0
    createOfflineQuoteRequest({
      body
    })
  }, [createOfflineQuoteRequest, offlineLocalData])

  const handleToAdditionalInfo = useCallback(() => {
    history.push(`/offline/quotes/additional/info/${offlineQuoteDetailData.id}`)
  }, [history, offlineQuoteDetailData.id])

  const handleInstantChecked = useCallback((checked) => {
    that.current.instantChecked = checked
  }, [])

  // const handleInstalmentPay = useCallback(() => {
  //   // redirect to payment page
  //   // use protection case for differentiate the product
  //   history.push({
  //     pathname: `/payment/${offlineQuoteDetailData?.policy_details?.protection_case}/${offlineQuoteDetailData.id}`
  //   })
  // }, [history, offlineQuoteDetailData])

  const renderInfoSection = useCallback(() => {
    if (
      (pageConfig.isOfflineOrderDetail && (!offlineQuoteDetailData.remarks) && (offlineQuoteDetailData.status !== ADDITIONAL_INFORMATION_REQUIRED))
    ) {
      return null
    }
    let info = (pageConfig.isOfflineOrderDetail ? offlineQuoteDetailData.remarks : LANG_STRINGS.reviewYourDetailsBeforeSubmit)
    if (offlineQuoteDetailData.status === ADDITIONAL_INFORMATION_REQUIRED) {
      info = LANG_STRINGS.someAdditionalInfoRequired
    }
    return (
      <>
        <InfoHeader
          info={info}
          bgColor={offlineQuoteDetailData.remarks ? AgentColorPallette.maroonRed : AgentColorPallette.black}
        />
        {
          offlineQuoteDetailData.status === ADDITIONAL_INFORMATION_REQUIRED && (
            <Row
              justify='space-between'
              align='center'
              className='additional-info-btn'
              onClick={handleToAdditionalInfo}
            >
              <CustomText
                size='14px'
                color={AgentColorPallette.black}
                weight={700}
              >
                {LANG_STRINGS.additionalInfo}
              </CustomText>
              <CustomText color={AgentColorPallette.fontSecondary} weight={700}>
                <i className='fas fa-angle-right' />
              </CustomText>
            </Row>
          )
        }
      </>
    )
  }, [pageConfig, offlineQuoteDetailData, handleToAdditionalInfo])
  return (
    <Container
      title={pageConfig.title}
      hideBottomTabs
      loader={CREATE_OFFLINE_QUOTE_LOADER || OFFLINE_QUOTE_DETAIL_LOADER || (pageConfig.isManualOrder === undefined)}
      backBtnId={pageConfig.isOfflineOrderDetail ? 'offlineOrderDetailBack' : 'mobilManualOrderStepBack_3'}
    >
      <OfflinePolicyReviewStyle>
        {
          !pageConfig.isOfflineOrderDetail && (
            <StepsHeader
              className='application-steps-header'
              leftText={LANG_STRINGS.review}
              current='3'
              totalSteps='3'
            />
          )
        }
        {
          renderInfoSection()
        }
        {
          (pageConfig.isManualOrder !== undefined) && (
            <OfflinePolicyContainer
              history={history}
              pageConfig={pageConfig}
              policyData={offlineLocalData}
              onInstantChecked={handleInstantChecked}
              quoteData={offlineQuoteDetailData}
            />
          )
        }
        {/* {
          !isEmpty(offlineQuoteDetailData?.instalment_details) && (
            <BottomBtn
              title={`${LANG_STRINGS.payInstalmentTo}-1`}
              icon={SEND_GOLD_ICON}
              onClick={handleInstalmentPay}
            />
          )
        } */}
        {
          !pageConfig.isOfflineOrderDetail && (
            <BottomBtn
              title={LANG_STRINGS.submitCalculation}
              icon={SEND_GOLD_ICON}
              onClick={handleSubmit}
              disabled={disabledBtn}
            />
          )
        }
      </OfflinePolicyReviewStyle>
      <ShowSnackbar />
    </Container>
  )
}

export default OfflinePolicyReviewContainer
